# given — read it and use it, no need to change it
def distance_matrix(d1, d2):
    """Every distance between the descriptors of picture 1 (rows) and picture 2 (columns): float64 (N, M).
    uint8 rows (ORB, 256 bits) are compared with the Hamming distance, anything else with the Euclidean (L2) one.

    Example: distance_matrix(np.array([[0.0, 0.0], [3.0, 4.0]]), np.array([[3.0, 0.0]])) → [[3.], [4.]]
    """
    # from mission 22 — finished: read it, use it, do not change it
    a, b = np.asarray(d1), np.asarray(d2)
    if len(a) == 0 or len(b) == 0:
        return np.zeros((len(a), len(b)))
    if a.dtype == np.uint8 and b.dtype == np.uint8:
        x = np.bitwise_xor(a[:, None, :], b[None, :, :])
        return np.unpackbits(x, axis=2).sum(axis=2).astype(np.float64)
    a, b = a.astype(np.float64), b.astype(np.float64)
    sq = (a * a).sum(1)[:, None] + (b * b).sum(1)[None, :] - 2.0 * a @ b.T
    return np.sqrt(np.maximum(sq, 0.0))


