# given — read it and use it, no need to change it
def similarity_matrix(s, theta_deg, tx, ty):
    """The 3 × 3 matrix of a similarity (s, theta_deg, tx, ty), for warp_points and cv2.warpPerspective.

    Example: similarity_matrix(2.0, 90.0, 5.0, 5.0) → [[0, -2, 5], [2, 0, 5], [0, 0, 1]] (up to rounding)
    """
    # from mission 22 — finished: read it, use it, do not change it
    c, s_ = s * math.cos(math.radians(theta_deg)), s * math.sin(math.radians(theta_deg))
    return np.array([[c, -s_, tx], [s_, c, ty], [0.0, 0.0, 1.0]])


# given — read it and use it, no need to change it
def normalise_points(pts):
    """Hartley's normalisation (lesson §3): the matrix T that moves the points' centroid to (0, 0) and scales them
    so that their mean distance from it is √2. Returns (pts_n, T), pts_n = the points mapped by T, float64 (N, 2).
    Points all at one place: T only moves them (scale 1).

    Example: normalise_points([[0, 0], [2, 0], [2, 2], [0, 2]])[0] → [[-1, -1], [1, -1], [1, 1], [-1, 1]]
    """
    # from mission 22 — finished: read it, use it, do not change it
    p = np.asarray(pts, dtype=np.float64).reshape(-1, 2)
    c = p.mean(axis=0)
    mean_d = np.hypot(*(p - c).T).mean()
    k = math.sqrt(2.0) / mean_d if mean_d > 1e-12 else 1.0
    T = np.array([[k, 0.0, -k * c[0]], [0.0, k, -k * c[1]], [0.0, 0.0, 1.0]])
    return (p - c) * k, T


