MIN_SAMPLE = {"similarity": 2, "homography": 4}


# given — read it and use it, no need to change it
def fit_model(kind, src, dst):
    """The 3 × 3 matrix of a model fitted to src → dst with YOUR fit_similarity (kind "similarity") or YOUR
    dlt_homography (kind "homography"), or None when the points cannot define one (a degenerate sample: points on
    top of each other, three in a line, a result that is not finite).

    Example: fit_model("similarity", [[0, 0], [10, 0]], [[5, 5], [5, 25]]) → [[0, -2, 5], [2, 0, 5], [0, 0, 1]]
             fit_model("similarity", [[3, 3], [3, 3]], [[1, 1], [2, 2]]) → None
    """
    # from mission 22 — finished: read it, use it, do not change it
    if kind not in MIN_SAMPLE:
        raise ValueError(f"kind must be 'similarity' or 'homography', got {kind!r}")
    try:
        if kind == "similarity":
            M = similarity_matrix(*fit_similarity(src, dst))
        else:
            M = np.asarray(dlt_homography(src, dst), dtype=np.float64)
    except (ValueError, np.linalg.LinAlgError, ZeroDivisionError, FloatingPointError):
        return None
    if M is None or not np.all(np.isfinite(M)) or abs(np.linalg.det(M[:2, :2])) < 1e-9:
        return None
    if kind == "homography":
        s_ = np.asarray(src, dtype=np.float64).reshape(-1, 2)
        if len(s_) >= 3:
            v = s_[1:] - s_[0]
            if np.abs(v[:, 0, None] * v[None, :, 1] - v[:, 1, None] * v[None, :, 0]).max() < 1e-6:
                return None                                     # all the src points on one line
    return M


