# given — read it and use it, no need to change it
def ransac_similarity(src, dst, thr_px=6.0, iters=200, rng=None):
    """YOUR ransac() for a similarity, returned as numbers: ((s, theta_deg, tx, ty), inliers), or (None, inliers)
    when no model was found. The fit is YOUR fit_similarity on the inliers.

    Example: with the pairs of ransac()'s example: ransac_similarity(src, dst, 1.0, 20, np.random.default_rng(1))
             → ((2.0, 0.0, 0.0, 0.0), [True] * 8 + [False, False])   (up to rounding)
    """
    # from mission 22 — finished: read it, use it, do not change it
    M, inl = ransac(src, dst, "similarity", thr_px, iters, rng)
    if M is None:
        return None, inl
    s_ = np.asarray(src, dtype=np.float64).reshape(-1, 2)
    d_ = np.asarray(dst, dtype=np.float64).reshape(-1, 2)
    return fit_similarity(s_[inl], d_[inl]), inl


